package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StringEscapeUtils.escapeJava(Writer out, String str)
 */
public class StringEscapeUtils_escapeJava_TriageGen4Test {

    @Test
    public void testEscapeJava_NullString() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, null);
        assertEquals("", out.toString());
    }

    @Test
    public void testEscapeJava_EmptyString() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "");
        assertEquals("", out.toString());
    }

    @Test
    public void testEscapeJava_PlainString() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "hello world");
        assertEquals("hello world", out.toString());
    }

    @Test
    public void testEscapeJava_SpecialCharacters() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "quote: \", backslash: \\, newline: \n, tab: \t, carriage return: \r");
        assertEquals("quote: \\\", backslash: \\\\, newline: \\n, tab: \\t, carriage return: \\r", out.toString());
    }

    @Test
    public void testEscapeJava_UnicodeCharacters() throws IOException {
        StringWriter out = new StringWriter();
        // Testing non-printable and unicode characters
        StringEscapeUtils.escapeJava(out, "\u0000\u001F\u03B1");
        assertEquals("\\u0000\\u001F\\u03B1", out.toString());
    }

    @Test
    public void testEscapeJava_MixedContent() throws IOException {
        StringWriter out = new StringWriter();
        String input = "Line 1\nLine 2\t\"Double Quotes\"";
        StringEscapeUtils.escapeJava(out, input);
        assertEquals("Line 1\\nLine 2\\t\\\"Double Quotes\\\"", out.toString());
    }

    @Test
    public void testEscapeJava_ThrowsIOException() throws IOException {
        // Custom Writer that always throws IOException to test exception propagation
        class ThrowingWriter extends java.io.Writer {
            @Override
            public void write(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("Simulated IO failure");
            }

            @Override
            public void flush() throws IOException {}

            @Override
            public void close() throws IOException {}
        }

        ThrowingWriter writer = new ThrowingWriter();
        try {
            StringEscapeUtils.escapeJava(writer, "test");
            org.junit.Assert.fail("Should have thrown IOException");
        } catch (IOException e) {
            assertEquals("Simulated IO failure", e.getMessage());
        }
    }
}
